const e={"home.about.card.list.0":"ಉತ್ಪನ್ನ ದಿಕ್ಕು ಸಂಶೋಧನೆ ಮತ್ತು ಮಾನ್ಯತೆ (ಚಾಲುದಲ್ಲಿದೆ)","home.about.card.list.1":"ಮೂಲ ಸಾಮರ್ಥ್ಯ ಅಭಿವೃದ್ಧಿ: ಎಂಜಿನಿಯರಿಂಗ್ ವ್ಯವಸ್ಥೆ / ಡೇಟಾ ಮತ್ತು ಸೇವಾ ಸಾಮರ್ಥ್ಯಗಳು / ಮೂಲಸೌಕರ್ಯ","home.about.card.list.2":"ಪ್ರೋಟೋಟೈಪಿಂಗ್ ಮತ್ತು ವೇಗದ ಪುನರಾವೃತ್ತ: ಆಲೋಚನೆಯಿಂದ ಬಳಸಬಹುದಾದ ಆವೃತ್ತಿಗೆ","home.about.card.list.3":"ಅನುಕೂಲತೆ ಮತ್ತು ಭದ್ರತೆ: ಡೇಟಾ ಭದ್ರತೆ ಮತ್ತು ಗೌಪ್ಯತಾ ರಕ್ಷಣೆಯನ್ನು ಒತ್ತಿಸುತ್ತಿದೆ","home.about.card.note":"ವ್ಯವಹಾರದ ವ್ಯಾಪ್ತಿಯು ಇನ್ನೂ ಅನ್ವೇಷಣಾ ಹಂತದಲ್ಲಿರುವುದರಿಂದ...","home.about.card.title":"ನಾವು ಏನು ಮಾಡುತ್ತಿದ್ದೇವೆ?","home.about.desc.0":"ನಾವು ಸ್ವಯಂ-ಶೋಧನೆಗೆ ಕೇಂದ್ರೀಕೃತವಾದ ನೆಟ್ವರ್ಕ್ ತಂತ್ರಜ್ಞಾನ ಕಂಪನಿಯಾಗಿದೆ...","home.about.desc.1":"ಪ್ರಸ್ತುತ ವ್ಯಾಪಾರ ವ್ಯಾಪ್ತಿಯು ಇನ್ನೂ ನಿರಂತರ ಅನ್ವೇಷಣೆಯ ಅಡಿಯಲ್ಲಿ ಇದೆ...","home.about.hl.0.num":"ಸ್ವಯಂ ಅಭಿವೃದ್ಧಿಪಡಿಸಿದ ಮೊದಲ","home.about.hl.0.text":"ತಮ್ಮದೇ ಆದ ಉತ್ಪನ್ನಗಳು ಮತ್ತು ವ್ಯಾಪಾರದಲ್ಲಿ ನಿರಂತರ ಹೂಡಿಕೆ.","home.about.hl.1.num":"ಸ್ಥಿರ ಪುನರಾವೃತ್ತ","home.about.hl.1.text":"ಇಂಜಿನಿಯರಿಂಗ್ ಗುಣಮಟ್ಟ, ನಿರ್ವಹಣಾ ಸಾಮರ್ಥ್ಯ ಮತ್ತು ವಿಸ್ತರಣೀಯತೆಯನ್ನು ಒತ್ತಿಸಿ.","home.about.hl.2.num":"ನಿರಂತರವಾಗಿ ಅನ್ವೇಷಿಸುತ್ತಿರುವ","home.about.hl.2.text":"ವ್ಯವಹಾರ ದಿಕ್ಕುಗಳ ಚಲನೆಯು ಹಂತ ಹಂತವಾಗಿ ಸ್ಪಷ್ಟ ಗಡಿಗಳನ್ನು ರೂಪಿಸುತ್ತದೆ.","home.about.title":"ನಮ್ಮ ಬಗ್ಗೆ","home.brand.en":"ಟ್ರೀಹೌಸ್ ಟೆಕ್ · ಶಾಂಘೈ","home.common.city":"ಶಾಂಘೈ · SHANGHAI","home.common.company":"上海树下小屋网络科技有限公司","home.common.email":"house@sxxw.site","home.common.email_mailto":"mailto:house@sxxw.site","home.contact.hint":"ನೀವು ನಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಲು ಅಗತ್ಯವಿದ್ದರೆ, ದಯವಿಟ್ಟು ಇಮೇಲ್ ಮೂಲಕ ಸಂಪರ್ಕಿಸಿ...","home.contact.label.city":"ನಗರ","home.contact.label.company":"ಕಂಪನಿಯ ಹೆಸರು","home.contact.label.email":"ಇಮೇಲ್","home.contact.title":"ಸಂಪರ್ಕ ಮಾಹಿತಿ","home.footer.legal":"© 2025 上海树下小屋网络科技有限公司","home.footer.links.about":"ನಮ್ಮ ಬಗ್ಗೆ","home.footer.links.contact":"ನಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಿ","home.footer.links.home":"ಮನೆ","home.footer.slogan":"ಸ್ವಾಯತ್ತ ಸಂಶೋಧನೆ ಮತ್ತು ಅಭಿವೃದ್ಧಿಯ ಮೇಲೆ ಕೇಂದ್ರೀಕೃತವಾಗಿರಿ · ನಿರಂತರ ಅನ್ವೇಷಣೆ · ಸ್ಥಿರ ಪುನಾವೃತ್ತ","home.hero.cta.about":"ನಮ್ಮ ಬಗ್ಗೆ ಹೆಚ್ಚು ತಿಳಿಯಿರಿ →","home.hero.cta.contact":"ಸಂಪರ್ಕ ಮಾಹಿತಿ","home.hero.desc":"ನಾವು ಸ್ವಾಯತ್ತ ಸಂಶೋಧನೆಗೆ ಕೇಂದ್ರೀಕೃತವಾದ ನೆಟ್‌ವರ್ಕ್ ತಂತ್ರಜ್ಞಾನ ಕಂಪನಿಯಾಗಿದೆ. ನಾವು ಅಮೂಲ್ಯ ಉತ್ಪನ್ನ ದಿಕ್ಕುಗಳು ಮತ್ತು ತಾಂತ್ರಿಕ ಕಾರ್ಯಗತಗೊಳಿಸುವ ಮಾರ್ಗಗಳನ್ನು ನಿರಂತರವಾಗಿ ಅನ್ವೇಷಿಸುತ್ತೇವೆ, ದೀರ್ಘಕಾಲದ ಪುನರಾವೃತ್ತ ಮತ್ತು ಸ್ಥಿರ ವಿತರಣೆಯನ್ನು ಗುರಿಯಾಗಿಸಿಕೊಂಡಿದ್ದೇವೆ.","home.hero.glass":'ದಿಕ್ಕು ಅನ್ವೇಷಣೆ → ಇಂಜಿನಿಯರಿಂಗ್ ಕಾರ್ಯಗತಗೊಳಣೆ → ಉತ್ಪನ್ನ ಶುದ್ಧೀಕರಣ <span class="dot"></span> ದೀರ್ಘಕಾಲಿಕತೆ / ಸ್ಥಿರ ವಿತರಣಾ',"home.hero.meta.0.label":"ಉತ್ಪನ್ನ ಮತ್ತು ಇಂಜಿನಿಯರಿಂಗ್ ಕೇಂದ್ರೀಕೃತ","home.hero.meta.0.num":"ಸ್ವಯಂ ಅಭಿವೃದ್ಧಿ","home.hero.meta.1.label":"ನಿರಂತರ ಪುನರಾವೃತ್ತ ಮತ್ತು ಸುಧಾರಣೆ","home.hero.meta.1.num":"ದೀರ್ಘಕಾಲಿಕ","home.hero.meta.2.label":"ಗುಣಮಟ್ಟ ಮತ್ತು ಅನುಕೂಲತೆಯನ್ನು ಒತ್ತಿಸಿ","home.hero.meta.2.num":"ಸ್ಥಿರ","home.hero.mini.foot":"* ಪ್ರಸ್ತುತ ಅಧಿಕೃತ ವೆಬ್‌ಸೈಟ್ ಒಂದು ಮೂಲ ಪರಿಚಯ ಪುಟವಾಗಿದೆ, ಮತ್ತು ವ್ಯವಹಾರವು ಮುಂದುವರಿಯುವಂತೆ ವಿಷಯವನ್ನು ನಿರಂತರವಾಗಿ ನವೀಕರಿಸಲಾಗುತ್ತದೆ.","home.hero.mini.head":"ಟಿಪ್","home.hero.mini.main":"ನಿರಂತರವಾಗಿ ವ್ಯಾಪಾರ ದಿಕ್ಕುಗಳನ್ನು ಅನ್ವೇಷಿಸುತ್ತಿರುವುದು","home.hero.mini.stats.0.k":"ಕೇಂದ್ರಿತ","home.hero.mini.stats.0.v":"ಸ್ವಯಂ ಅಭಿವೃದ್ಧಿ ಮಾಡಿದ ಉತ್ಪನ್ನ","home.hero.mini.stats.1.k":"ರೂಪ","home.hero.mini.stats.1.v":"ಹೆಚ್ಚಾಗಿ ಸ್ಪಷ್ಟಪಡಿಸಿ","home.hero.mini.stats.2.k":"ರಿದಮ್","home.hero.mini.stats.2.v":"ಆವೃತ್ತಿ ಪ್ರಗತಿ","home.hero.mini.stats.3.k":"ಗುರಿ","home.hero.mini.stats.3.v":"ಸ್ಥಾಯೀ ಬೆಳವಣಿಗೆ","home.hero.title":'<span class="accent"> ಸ್ವಾಯತ್ತ ಸಂಶೋಧನೆ ಮತ್ತು ಅಭಿವೃದ್ಧಿ </span> ಮತ್ತು ಉತ್ಪನ್ನ ಅನ್ವೇಷಣೆ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸುತ್ತಿದೆ',"home.html.lang":"ಕನ್ನಡ","home.meta.description":"上海树下小屋网络科技有限公司 - ಸ್ವಾಯತ್ತ ಸಂಶೋಧನೆ ಮತ್ತು ಉತ್ಪನ್ನ ಅನ್ವೇಷಣೆಯ ಮೇಲೆ ಕೇಂದ್ರೀಕೃತವಾಗಿದೆ","home.meta.title":"上海树下小屋网络科技有限公司","home.nav.about":"ನಮ್ಮ ಬಗ್ಗೆ","home.nav.contact":"ನಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಿ","home.nav.home":"ಮನೆ","home.nav.toggle":"ಮೆನು ವಿಸ್ತಾರಗೊಳಿಸಿ","home.noscript":"ಈ ತಾಣವು ಸಂಪೂರ್ಣ ಪರಸ್ಪರ ಅನುಭವಕ್ಕಾಗಿ (ನಾವಿಗೇಶನ್ ಮೆನು, ಸ್ಕ್ರೋಲಿಂಗ್ ಪರಿಣಾಮಗಳು, ಇತ್ಯಾದಿ) ಜಾವಾಸ್ಕ್ರಿಪ್ಟ್ ಅನ್ನು ಅಗತ್ಯವಿದೆ.","nav.apps":"ಆ್ಯಪ್ ಸೆಂಟರ್","nav.support":"ಬೆಂಬಲ","apps.hero.eyebrow":"sxxw.site · ಆ್ಯಪ್ ಬೆಂಬಲ ಕೇಂದ್ರ","apps.hero.title":"ಪ್ರತಿ ಆ್ಯಪ್ ಸ್ಪಷ್ಟ ಮಾರ್ಗದರ್ಶನ ಮತ್ತು ನೀವು ನಿಯಂತ್ರಿಸುವ ಡೇಟಾ ಗಡಿಗಳೊಂದಿಗೆ ಬರುತ್ತದೆ.","apps.hero.desc":"ಇಲ್ಲಿ ಉತ್ಪನ್ನದ ಅವಲೋಕನ, ಆರಂಭಿಕ ಮಾರ್ಗದರ್ಶಿಗಳು, ಗೌಪ್ಯತಾ ನೀತಿ, ನಿಯಮಗಳು ಮತ್ತು ತಾಂತ್ರಿಕ ಬೆಂಬಲ ಸಿಗುತ್ತದೆ. ನೀವು ನಿಜವಾಗಿ ಬಳಸುವ ವೇದಿಕೆಯ ವಿಭಾಗವನ್ನು ಓದಿ.","apps.card.cta":"ಆ್ಯಪ್ ನೋಡಿ","apps.memoria.desc":"ಹುಟ್ಟುಹಬ್ಬ, ವಾರ್ಷಿಕೋತ್ಸವ ಮತ್ತು ಕೌಂಟ್‌ಡೌನ್‌ಗಳನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಿ. iOS ಆವೃತ್ತಿ ಐಚ್ಛಿಕ ಖಾಸಗಿ iCloud ಸಿಂಕ್ ಬೆಂಬಲಿಸುತ್ತದೆ; Huawei AppGallery-ನ Memoria ಆವೃತ್ತಿ ಸಂಪೂರ್ಣವಾಗಿ ಸಾಧನದಲ್ಲೇ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ.","apps.memoria.tag":"ವಾರ್ಷಿಕೋತ್ಸವ · ಜ್ಞಾಪನೆಗಳು","apps.timetrails.desc":"ಗೌಪ್ಯತೆ-ಮೊದಲ GPS ಟ್ರ್ಯಾಕ್ ಲಾಗಿಂಗ್: ಪ್ರಯಾಣ, ವ್ಯಾಯಾಮ ಮತ್ತು ಸಂಚಾರಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ದಾಖಲಿಸುತ್ತದೆ, ನಕ್ಷೆಯಲ್ಲಿ ನಿಮ್ಮ ಹೆಜ್ಜೆಗುರುತುಗಳನ್ನು ಬಿಡಿಸುತ್ತದೆ ಮತ್ತು ನೀವು ಭೇಟಿ ನೀಡಿದ ನಗರಗಳನ್ನು ಬೆಳಗಿಸುತ್ತದೆ. ಟ್ರ್ಯಾಕ್‌ಗಳು ಡೀಫಾಲ್ಟ್ ಆಗಿ ಸಾಧನದಲ್ಲೇ ಇರುತ್ತವೆ, ಐಚ್ಛಿಕ ಖಾಸಗಿ iCloud ಬ್ಯಾಕಪ್‌ನೊಂದಿಗೆ.","apps.timetrails.tag":"GPS ಟ್ರ್ಯಾಕ್ · ಮಾರ್ಗಗಳು","apps.traceapp.desc":"ಮಾರ್ಗ, ದೂರ, ವೇಗ ಮತ್ತು ಪೇಸ್ ದಾಖಲಿಸುತ್ತದೆ. ಖಾತೆ ಇಲ್ಲ, ಬಿಲ್ಟ್-ಇನ್ ಜಾಹೀರಾತು ಅಥವಾ ಮೂರನೇ ಪಕ್ಷದ ಅನಾಲಿಟಿಕ್ಸ್ ಇಲ್ಲ.","apps.traceapp.tag":"ಮಾರ್ಗಗಳು · ಅಂಕಿಅಂಶ","apps.footer.slogan":"ಉತ್ಪನ್ನಗಳು · ಮಾರ್ಗದರ್ಶಿಗಳು · ಗೌಪ್ಯತೆ ಮತ್ತು ಬೆಂಬಲ","support.brand":"ಬೆಂಬಲ","support.hero.eyebrow":"sxxw.site · ಬೆಂಬಲ ಕೇಂದ್ರ","support.hero.title":"ನಿಮಗೆ ಸೂಕ್ತವಾದ ರೀತಿಯಲ್ಲಿ TreeHouse ಅನ್ನು ಸಂಪರ್ಕಿಸಿ.","support.hero.desc":"TreeHouse ಆ್ಯಪ್‌ಗಳ ಎಲ್ಲಾ ಅಧಿಕೃತ ಬೆಂಬಲ ಚಾನೆಲ್‌ಗಳು ಒಂದೇ ಸ್ಥಳದಲ್ಲಿ: ಪ್ರತಿಕ್ರಿಯೆ, ಆ್ಯಪ್-ಸ್ಟೋರ್ ವಿಮರ್ಶೆಗಳು ಮತ್ತು ಅಧಿಕೃತ ಸಮುದಾಯ ಗುಂಪುಗಳು. ಲೋಕಲ್-ಫಸ್ಟ್, ಜಾಹೀರಾತಿಲ್ಲ, ಮೂರನೇ ಪಕ್ಷದ ಟ್ರ್ಯಾಕಿಂಗ್ ಇಲ್ಲ.","support.g1.title":"ಪ್ರತಿಕ್ರಿಯೆ","support.g1.note":"ಸಮಸ್ಯೆ ಎದುರಾಯಿತೇ ಅಥವಾ ಸಲಹೆ ಇದೆಯೇ? ಕೆಳಗಿನ ಯಾವುದೇ ವಿಧಾನದಲ್ಲಿ ನಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಿ — ನಾವು ಪ್ರತಿ ಸಂದೇಶವನ್ನೂ ಓದುತ್ತೇವೆ.","support.g1.feedback.name":"ಆ್ಯಪ್ ಒಳಗಿನ ಪ್ರತಿಕ್ರಿಯೆ","support.g1.feedback.desc":"ಪ್ರತಿ ಆ್ಯಪ್ ಒಳಗಿನಿಂದಲೇ ಕಳುಹಿಸಿ; ನಿಮ್ಮ ಆವೃತ್ತಿ, ಸಾಧನ ಮತ್ತು ಸಿಸ್ಟಮ್ ಮಾಹಿತಿ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಲಗತ್ತಾಗುತ್ತದೆ, ಇದರಿಂದ ನಾವು ಬೇಗ ಪರಿಶೀಲಿಸಬಹುದು.","support.g1.feedback.cta":"ಆ್ಯಪ್‌ಗಳನ್ನು ನೋಡಿ","support.g1.email.name":"ಇಮೇಲ್ ಕಳುಹಿಸಿ","support.g1.email.desc":"ಔಪಚಾರಿಕ ವಿನಂತಿಗಳು ಮತ್ತು ಗೌಪ್ಯತೆ ಅಥವಾ ಖಾತೆ ವಿಷಯಗಳಿಗೆ ಇಮೇಲ್‌ನಲ್ಲಿ ಹೆಚ್ಚು ಸಂಪೂರ್ಣ ಉತ್ತರ ಸಿಗುತ್ತದೆ.","support.g1.email.cta":"ಇಮೇಲ್ ಕಳುಹಿಸಿ","support.g2.title":"ಆ್ಯಪ್‌ಗಳಿಗೆ ರೇಟಿಂಗ್ ನೀಡಿ (ಪ್ರತಿ ಆ್ಯಪ್‌ಗೆ)","support.g2.note":"ಇಷ್ಟವಾದರೆ ನೀವು ಬಳಸುವ ಸ್ಟೋರ್‌ನಲ್ಲಿ ವಿಮರ್ಶೆ ಬರೆಯಿರಿ — ನಾವು ನೋಡುತ್ತೇವೆ ಮತ್ತು ಉತ್ತರಿಸುತ್ತೇವೆ. ನಿಮ್ಮ ಆ್ಯಪ್‌ಗೆ ಹೊಂದುವುದನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ.","support.g2.cta.write":"ವಿಮರ್ಶೆ ಬರೆಯಿರಿ","support.g2.cta.goto":"ವಿಮರ್ಶೆಗೆ ಹೋಗಿ","support.g2.memoria.huawei.platform":"HarmonyOS · Huawei ಸಾಧನಗಳು","support.g3.title":"WeChat · QQ · Telegram ಗುಂಪುಗಳು","support.g3.note":"ನವೀಕರಣಗಳು ಮತ್ತು ಸಹ-ಬಳಕೆದಾರರ ಸಹಾಯಕ್ಕಾಗಿ ನಮ್ಮ ಅಧಿಕೃತ ಗುಂಪುಗಳಿಗೆ ಸೇರಿ: ಚೀನಾದಲ್ಲಿ WeChat / QQ, ಬೇರೆಡೆ Telegram.","support.g3.wechat.name":"WeChat ಗುಂಪು","support.g3.wechat.desc":"ದೈನಂದಿನ ಚಾಟ್ ಮತ್ತು ಸಹಾಯ. ಗುಂಪು ತುಂಬಿದಾಗ ಹೊಸ QR ಕೋಡ್ ಪೋಸ್ಟ್ ಮಾಡಲಾಗುತ್ತದೆ.","support.g3.qq.name":"QQ ಗುಂಪು","support.g3.qq.desc":"ಚೀನಾದ ಬಳಕೆದಾರರಿಗೆ; ಹೆಚ್ಚಿನ ಸದಸ್ಯ ಸಾಮರ್ಥ್ಯ.","support.g3.tg.name":"Telegram ಗುಂಪು","support.g3.tg.desc":"ಅಂತರರಾಷ್ಟ್ರೀಯ ಬಳಕೆದಾರರಿಗೆ ಚಾಟ್ ಮತ್ತು ಪ್ರಶ್ನೋತ್ತರ.","support.g3.join":"ಸೇರಿ","support.pending":"ಶೀಘ್ರದಲ್ಲೇ","support.foot":"ಸರಿಯಾದ ಚಾನೆಲ್ ಸಿಗಲಿಲ್ಲವೇ? house@sxxw.site ಗೆ ಇಮೇಲ್ ಮಾಡಿ, ನಾವು ಉತ್ತರಿಸುತ್ತೇವೆ.","support.footer.slogan":"ಪ್ರತಿಕ್ರಿಯೆ · ಆ್ಯಪ್-ಸ್ಟೋರ್ ವಿಮರ್ಶೆಗಳು · ಸಮುದಾಯ ಗುಂಪುಗಳು","mem.ios.tagline":"ಹುಟ್ಟುಹಬ್ಬ, ವಾರ್ಷಿಕೋತ್ಸವ ಮತ್ತು ವಿಶೇಷ ದಿನಗಳನ್ನು ದಾಖಲಿಸಿ, ಸಮಯವನ್ನು ಮೃದುವಾಗಿ ಕಾಣಿಸಿ.","mem.ios.desc":"ಹುಟ್ಟುಹಬ್ಬ, ವಾರ್ಷಿಕೋತ್ಸವ, ಪ್ರೀತಿಯ ವಾರ್ಷಿಕೋತ್ಸವ, ಹಬ್ಬ ಮತ್ತು ನಿಮಗೆ ಪ್ರಿಯವಾದ ದಿನಗಳನ್ನು ಒಂದೇ ಶಾಂತ ಜಾಗದಲ್ಲಿ ಇರಿಸಿ. ಹಿಂಗಣನೆಯಿಂದ ಇನ್ನೂ ಎಷ್ಟು ದಿನ ಬಾಕಿ ಎಂದು ನೋಡಿ, ಮುಂಗಣನೆಯಿಂದ ಎಷ್ಟು ದಿನ ಕಳೆಯಿತು ಎಂದು ಉಳಿಸಿ.","mem.ios.feat.0":"ಹುಟ್ಟುಹಬ್ಬ, ವಾರ್ಷಿಕೋತ್ಸವ, ಹಬ್ಬ ಮತ್ತು ಸ್ವಂತ ಈವೆಂಟ್‌ಗಳು","mem.ios.feat.1":"ಗ್ರೆಗೋರಿಯನ್ ಮತ್ತು ಚೀನೀ ಚಾಂದ್ರ ದಿನಾಂಕಗಳು","mem.ios.feat.2":"ಹಿಂಗಣನೆ, ಮುಂಗಣನೆ ಮತ್ತು ಜೀವನದ ಪ್ರಗತಿ","mem.ios.feat.3":"ಸ್ಥಳೀಯ ಜ್ಞಾಪನೆ, ಹೋಮ್ ಸ್ಕ್ರೀನ್ ಮತ್ತು ಲಾಕ್ ಸ್ಕ್ರೀನ್ ವಿಜೆಟ್‌ಗಳು","mem.ios.feat.4":"Apple Watch ನಲ್ಲಿ ತ್ವರಿತ ನೋಟ","mem.ios.feat.5":"ಐಚ್ಛಿಕ iCloud ಖಾಸಗಿ ಸಿಂಕ್","mem.ios.guide.0.t":"ಮೊದಲ ದಾಖಲೆ ರಚಿಸಿ","mem.ios.guide.0.b":"ಆ್ಯಪ್ ತೆರೆದು ಸೇರಿಸಿ ಆಯ್ಕೆ ಮಾಡಿ, ಹೆಸರು, ದಿನಾಂಕ ಮತ್ತು ಉಳಿಸಬೇಕಾದ ಟಿಪ್ಪಣಿ ಭರ್ತಿ ಮಾಡಿ. ಅಗತ್ಯಕ್ಕೆ ತಕ್ಕಂತೆ ಹುಟ್ಟುಹಬ್ಬ, ವಾರ್ಷಿಕೋತ್ಸವ, ಹಬ್ಬ ಅಥವಾ ಸ್ವಂತ ಈವೆಂಟ್ ಆಯ್ಕೆ ಮಾಡಿ.","mem.ios.guide.1.t":"ದಿನಾಂಕ ನಿಯಮ ಆಯ್ಕೆ ಮಾಡಿ","mem.ios.guide.1.b":"ಹುಟ್ಟುಹಬ್ಬ ಮತ್ತು ವಾರ್ಷಿಕೋತ್ಸವಕ್ಕೆ ಗ್ರೆಗೋರಿಯನ್ ಅಥವಾ ಚೀನೀ ಚಾಂದ್ರ ಪಂಚಾಂಗ ಬಳಸಬಹುದು. ಚಾಂದ್ರ ದಾಖಲೆಗಳು ನಿಯಮದ ಪ್ರಕಾರ ಮುಂದಿನ ದಿನಾಂಕವನ್ನು ಲೆಕ್ಕಹಾಕಿ ತೋರಿಸುತ್ತವೆ.","mem.ios.guide.2.t":"ಜ್ಞಾಪನೆ ಹೊಂದಿಸಿ","mem.ios.guide.2.b":"ಪ್ರಮುಖ ದಿನಗಳಿಗೆ ಸ್ಥಳೀಯ ಅಧಿಸೂಚನೆ ಆನ್ ಮಾಡಿ, ಅದೇ ದಿನ ಅಥವಾ ಮುಂಚಿತ ಜ್ಞಾಪನೆ ಸಮಯ ಆಯ್ಕೆ ಮಾಡಿ. ಅಧಿಸೂಚನೆ ಅನುಮತಿ ಆಫ್ ಇದ್ದರೆ, ಆ್ಯಪ್ ಸಿಸ್ಟಂ ಸೆಟ್ಟಿಂಗ್ಸ್‌ಗೆ ಹೋಗಿ ಆನ್ ಮಾಡಲು ಸೂಚಿಸುತ್ತದೆ.","mem.ios.guide.3.t":"ಅಗತ್ಯಕ್ಕೆ ತಕ್ಕಂತೆ ಸಿಂಕ್ ಆನ್ ಮಾಡಿ","mem.ios.guide.3.b":"ನಿಮ್ಮ iPhone, iPad ಮತ್ತು Apple Watch ನಡುವೆ ಸಿಂಕ್ ಮಾಡಬೇಕಿದ್ದರೆ, iCloud ಗೆ ಲಾಗಿನ್ ಆಗಿರುವಾಗ ಸಿಂಕ್ ಆನ್ ಮಾಡಿ. ಡೇಟಾ ನಿಮ್ಮ CloudKit ಖಾಸಗಿ ಡೇಟಾಬೇಸ್‌ಗೆ ಹೋಗುತ್ತದೆ, ಡೆವಲಪರ್ ಅದನ್ನು ಓದಲಾಗದು.","mem.hm.tagline":"ಹುಟ್ಟುಹಬ್ಬ, ವಾರ್ಷಿಕೋತ್ಸವ ಮತ್ತು ವಿಶೇಷ ದಿನಗಳನ್ನು ಸಾಧನದಲ್ಲೇ ಸ್ಥಳೀಯವಾಗಿ ದಾಖಲಿಸಿ.","mem.hm.desc":"拾忆 ಎಂಬುದು HarmonyOS ವೇದಿಕೆಯಲ್ಲಿ Memoria · 拾忆 ನ ಸ್ಥಳೀಯ ಆವೃತ್ತಿ. ಖಾತೆ ಇಲ್ಲ, ಇಂಟರ್ನೆಟ್ ಇಲ್ಲ, ಕ್ಲೌಡ್ ಸಿಂಕ್ ಇಲ್ಲ; ಡೇಟಾ ಕೇವಲ ನಿಮ್ಮ ಸಾಧನದ ಆ್ಯಪ್ ಸ್ಯಾಂಡ್‌ಬಾಕ್ಸ್‌ನಲ್ಲಿ ಮಾತ್ರ ಉಳಿಯುತ್ತದೆ.","mem.hm.feat.0":"ಹುಟ್ಟುಹಬ್ಬ, ವಾರ್ಷಿಕೋತ್ಸವ, ಹಬ್ಬ ಮತ್ತು ಸ್ವಂತ ಈವೆಂಟ್‌ಗಳು","mem.hm.feat.1":"ಗ್ರೆಗೋರಿಯನ್ ಮತ್ತು ಚೀನೀ ಚಾಂದ್ರ ದಿನಾಂಕಗಳು","mem.hm.feat.2":"ಹಿಂಗಣನೆ, ಮುಂಗಣನೆ ಮತ್ತು ಜೀವನದ ಪ್ರಗತಿ","mem.hm.feat.3":"ಸ್ಥಳೀಯ ಜ್ಞಾಪನೆ","mem.hm.feat.4":"ರೀಸೈಕಲ್ ಬಿನ್‌ನಿಂದ ಮರುಪಡೆಯುವಿಕೆ ಮತ್ತು ಸಂಪೂರ್ಣ ಅಳಿಸುವಿಕೆ","mem.hm.feat.5":"ಖಾತೆ ಇಲ್ಲ, ಜಾಹೀರಾತು ಇಲ್ಲ, ನೆಟ್‌ವರ್ಕ್ ವಿನಂತಿ ಇಲ್ಲ","mem.hm.guide.0.t":"ಹೊಸ ವಾರ್ಷಿಕೋತ್ಸವ ಸೇರಿಸಿ","mem.hm.guide.0.b":"ವಾರ್ಷಿಕೋತ್ಸವ ಪುಟಕ್ಕೆ ಹೋಗಿ ಹೊಸದಾಗಿ ರಚಿಸಿ ಆಯ್ಕೆ ಮಾಡಿ, ಹೆಸರು, ದಿನಾಂಕ, ಪ್ರಕಾರ ಮತ್ತು ಟಿಪ್ಪಣಿ ಭರ್ತಿ ಮಾಡಿ. ಅಗತ್ಯವಿದ್ದರೆ ಚೀನೀ ಚಾಂದ್ರ ದಿನಾಂಕ ಆಯ್ಕೆ ಮಾಡಬಹುದು.","mem.hm.guide.1.t":"ಮುಂದಿನ ದಿನಾಂಕ ಖಚಿತಪಡಿಸಿ","mem.hm.guide.1.b":"ಉಳಿಸಿದ ನಂತರ ಆ್ಯಪ್ ದಿನಾಂಕ ಮತ್ತು ಪುನರಾವರ್ತನೆ ನಿಯಮದ ಪ್ರಕಾರ ಮುಂದಿನ ದಿನಾಂಕ ತೋರಿಸುತ್ತದೆ. ಚಾಂದ್ರ ದಾಖಲೆಗಳು ಸಂಬಂಧಿತ ನಿಯಮದಿಂದ ಪರಿವರ್ತನೆಯಾಗುತ್ತವೆ.","mem.hm.guide.2.t":"ಸ್ಥಳೀಯ ಜ್ಞಾಪನೆ ಹೊಂದಿಸಿ","mem.hm.guide.2.b":"ದಾಖಲೆಯಲ್ಲಿ ಜ್ಞಾಪನೆ ಸಮಯ ಮತ್ತು ಎಷ್ಟು ದಿನ ಮುಂಚಿತವಾಗಿ ತಿಳಿಸಬೇಕೆಂದು ಆಯ್ಕೆ ಮಾಡಿ. ಮೊದಲ ಬಾರಿ ಜ್ಞಾಪನೆ ಹೊಂದಿಸುವಾಗ ಸಿಸ್ಟಂ ಅಧಿಸೂಚನೆಗೆ ಅನುಮತಿ ನೀಡಿ; ಅನುಮತಿ ಆಫ್ ಆದರೆ ಜ್ಞಾಪನೆ ಮಾತ್ರ ಬಾಧಿತವಾಗುತ್ತದೆ, ದಾಖಲೆ ಮತ್ತು ವೀಕ್ಷಣೆ ಅಲ್ಲ.","mem.hm.guide.3.t":"ಸ್ಥಳೀಯ ಡೇಟಾ ನಿರ್ವಹಿಸಿ","mem.hm.guide.3.b":"ಅಳಿಸಿದ ದಾಖಲೆಗಳು ಮೊದಲು ರೀಸೈಕಲ್ ಬಿನ್‌ಗೆ ಹೋಗುತ್ತವೆ, ಅಲ್ಲಿಂದ ಮರುಪಡೆಯಬಹುದು ಅಥವಾ ಸಂಪೂರ್ಣ ಅಳಿಸಬಹುದು. ಆ್ಯಪ್ ಅನ್‌ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಿದರೆ ಸಾಧನದ ಆ್ಯಪ್ ಡೇಟಾ ಅಳಿಸಲ್ಪಡುತ್ತದೆ; ಕ್ಲೌಡ್ ಬ್ಯಾಕಪ್ ಇಲ್ಲದ ಕಾರಣ ಸಾಧನ ಬದಲಿಸಿದ ಅಥವಾ ಅನ್‌ಇನ್‌ಸ್ಟಾಲ್ ನಂತರ ಮರುಪಡೆಯಲಾಗದು.","tt.tagline":"GPS ಜಾಡು ದಾಖಲೆ, ನಡೆದ ದಾರಿ ನಿಮ್ಮದೇ ಸಮಯದಲ್ಲಿ ಉಳಿಯಲಿ.","tt.desc":"时光轨迹 TimeTrails ಎಂಬುದು ಗೌಪ್ಯತೆ-ಮೊದಲ GPS ಜಾಡು ದಾಖಲಿಸುವ ಆ್ಯಪ್. ಪ್ರಯಾಣ, ಓಟ, ಸೈಕ್ಲಿಂಗ್, ಚಾರಣ ಮತ್ತು ಚಾಲನೆಯ ದಾರಿಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ದಾಖಲಿಸುತ್ತದೆ, ನಕ್ಷೆಯಲ್ಲಿ ನಿಮ್ಮ ಹೆಜ್ಜೆಗಳನ್ನು ಜೀವಂತವಾಗಿ ತೋರಿಸಿ ನೀವು ಸುತ್ತಿದ ನಗರಗಳನ್ನು ಬೆಳಗಿಸುತ್ತದೆ. ಖಾತೆ ನೋಂದಣಿ ಬೇಕಿಲ್ಲ, ಜಾಹೀರಾತು ಅಥವಾ ಮೂರನೇ ಪಕ್ಷದ ಟ್ರ್ಯಾಕಿಂಗ್ ಇಲ್ಲ, ಜಾಡು ಡೇಟಾ ಪೂರ್ವನಿಯೋಜಿತವಾಗಿ ನಿಮ್ಮ ಸಾಧನದಲ್ಲೇ ಮಾತ್ರ ಉಳಿಯುತ್ತದೆ.","tt.feat.0":"ದೈನಂದಿನ ಚಲನೆಯ ದಾರಿ ಮತ್ತು ದೂರವನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ದಾಖಲಿಸಿ","tt.feat.1":"ಸ್ಥಳೀಯ ಸಮಯದ ಪ್ರಕಾರ ದೈನಂದಿನ ದಾರಿ ಮತ್ತು ಚಟುವಟಿಕೆ ಸಾರಾಂಶ","tt.feat.2":"ಮಂಜು ಶೋಧನೆಯಿಂದ ಹೋದ ಜಾಗಗಳನ್ನು ಮತ್ತೆ ನೋಡಿ","tt.feat.3":"ನಡಿಗೆ, ಸೈಕ್ಲಿಂಗ್, ಚಾಲನೆ ಮುಂತಾದ ಚಟುವಟಿಕೆ ಪ್ರಕಾರ ಗುರುತಿಸಿ","tt.feat.4":"ದಾರಿಯ ನೆನಪು ಉಳಿಸಲು ಐಚ್ಛಿಕ ಫೋಟೋ ಆಮದು","tt.feat.5":"ಐಚ್ಛಿಕ iCloud ಖಾಸಗಿ ಡೇಟಾಬೇಸ್ ಬ್ಯಾಕಪ್ ಮತ್ತು ಸಾಧನ ಬದಲಿಸಿ ಮರುಪಡೆಯುವಿಕೆ","tt.guide.0.t":"ಸ್ಥಳ ಅನುಮತಿ ಆಯ್ಕೆ ಮಾಡಿ","tt.guide.0.b":'ಹಿನ್ನೆಲೆಯಲ್ಲಿ ನಿರಂತರ ದಾಖಲೆಗೆ ಸಿಸ್ಟಂ ಸೂಚನೆಯಲ್ಲಿ "ಯಾವಾಗಲೂ" ಸ್ಥಳ ಮತ್ತು "ನಿಖರ ಸ್ಥಳ"ಕ್ಕೆ ಅನುಮತಿ ನೀಡಿ. ಯಾವಾಗ ಬೇಕಾದರೂ ಸಿಸ್ಟಂ ಸೆಟ್ಟಿಂಗ್ಸ್‌ನಲ್ಲಿ ಬದಲಾಯಿಸಬಹುದು.',"tt.guide.1.t":"ದಾಖಲೆ ಆರಂಭಿಸಿ","tt.guide.1.b":"ಮೊದಲ ಬಾರಿ ಪ್ರವೇಶಿಸಿ ದಾಖಲೆ ಆನ್ ಮಾಡಿ. ಆ್ಯಪ್‌ನಲ್ಲಿ ಯಾವಾಗ ಬೇಕಾದರೂ ವಿರಾಮ ಅಥವಾ ಮತ್ತೆ ಆರಂಭಿಸಬಹುದು, ನಿಯಂತ್ರಣ ನಿಮ್ಮ ಕೈಯಲ್ಲಿದೆ.","tt.guide.2.t":"ದೈನಂದಿನ ದಾರಿ ನೋಡಿ","tt.guide.2.b":"ಕ್ಯಾಲೆಂಡರ್ ಅಥವಾ ನಕ್ಷೆಯಲ್ಲಿ ಪ್ರತಿದಿನದ ದಾರಿ, ದೂರ, ನಿಲುಗಡೆ ಮತ್ತು ಚಟುವಟಿಕೆ ಸಾರಾಂಶವನ್ನು ಪರಿಶೀಲಿಸಿ.","tt.guide.3.t":"ಅಗತ್ಯಕ್ಕೆ ತಕ್ಕಂತೆ ಬ್ಯಾಕಪ್ ಆನ್ ಮಾಡಿ","tt.guide.3.b":"ಸಾಧನ ಬದಲಿಸಿ ಮರುಪಡೆಯಲು ಅಥವಾ ಹಲವು ಸಾಧನ ಸಿಂಕ್ ಬೇಕಿದ್ದರೆ ಸೆಟ್ಟಿಂಗ್ಸ್‌ನಲ್ಲಿ ನೀವೇ iCloud ಡೇಟಾ ಬ್ಯಾಕಪ್ ಆನ್ ಮಾಡಿ; ಪೂರ್ವನಿಯೋಜಿತವಾಗಿ ಆಫ್ ಇರುತ್ತದೆ.","trace.tagline":"ಪ್ರತಿ ಪ್ರಯಾಣವನ್ನೂ ದಾಖಲಿಸಿ, ನಿಯಂತ್ರಣವನ್ನೂ ನಿಮ್ಮ ಕೈಯಲ್ಲೇ ಇರಿಸಿ.","trace.desc":"出行轨迹 TraceApp ನಿಮಗೆ ದಾರಿ, ದೂರ, ವೇಗ ಮತ್ತು ಪೇಸ್ ದಾಖಲಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ, ಮತ್ತು ಡೇಟಾವನ್ನು ಸ್ಥಳೀಯ-ಮೊದಲ ರೀತಿಯಲ್ಲಿ ಉಳಿಸುತ್ತದೆ. ಖಾತೆ ಬೇಕಿಲ್ಲ, ಒಳಗೆ ಯಾವುದೇ ಮೂರನೇ ಪಕ್ಷದ ವಿಶ್ಲೇಷಣೆ ಅಥವಾ ಜಾಹೀರಾತು SDK ಇಲ್ಲ.","trace.feat.0":"ಪ್ರಯಾಣದ ದಾರಿ ದಾಖಲಿಸಿ ಮತ್ತು ತೋರಿಸಿ","trace.feat.1":"ದೂರ, ವೇಗ ಮತ್ತು ಪೇಸ್ ಅಂಕಿಅಂಶ","trace.feat.2":"ಜಾಡು ಮರುಪ್ಲೇ ಮತ್ತು ನಕ್ಷೆಯಲ್ಲಿ ದೃಶ್ಯೀಕರಣ","trace.feat.3":"ಐಚ್ಛಿಕ ಚಲನೆ-ಸ್ಥಿತಿ ಗುರುತಿಸುವಿಕೆ","trace.feat.4":"ಸಾಧನದ ಸ್ಯಾಂಡ್‌ಬಾಕ್ಸ್‌ನಲ್ಲಿ ಇತಿಹಾಸ ಉಳಿಸಿ","trace.feat.5":"ಐಚ್ಛಿಕ iCloud ಸಾಧನಗಳ ನಡುವೆ ಸಿಂಕ್","trace.guide.0.t":"ಸ್ಥಳ ಅನುಮತಿ ನೀಡಿ","trace.guide.0.b":'ಮೊದಲ ಬಾರಿ ಬಳಸುವಾಗ ಅಗತ್ಯಕ್ಕೆ ತಕ್ಕಂತೆ "App ಬಳಸುವಾಗ" ಅಥವಾ "ಯಾವಾಗಲೂ" ಸ್ಥಳ ಅನುಮತಿ ಆಯ್ಕೆ ಮಾಡಿ; ಅನುಮತಿ ಯಾವಾಗ ಬೇಕಾದರೂ ಸಿಸ್ಟಂ ಸೆಟ್ಟಿಂಗ್ಸ್‌ನಲ್ಲಿ ಬದಲಾಯಿಸಬಹುದು.',"trace.guide.1.t":"ಒಂದು ಪ್ರಯಾಣ ಆರಂಭಿಸಿ","trace.guide.1.b":"ಆ್ಯಪ್‌ನಲ್ಲಿ ದಾಖಲೆ ಆರಂಭಿಸಿ, ದಾರಿ, ದೂರ, ವೇಗ ಮತ್ತು ಪೇಸ್ ಪ್ರಸ್ತುತ ಸಾಧನದಲ್ಲಿ ಉಳಿಯುತ್ತವೆ.","trace.guide.2.t":"ಮರುಪ್ಲೇ ಮತ್ತು ವ್ಯವಸ್ಥೆ","trace.guide.2.b":"ಇತಿಹಾಸದಲ್ಲಿ ದಾರಿ ಮತ್ತು ಅಂಕಿಅಂಶ ನೋಡಿ, ಬೇಡವಾದ ದಾಖಲೆ ಅಳಿಸಿ, ಅಥವಾ ಸಿಸ್ಟಂ ಹಂಚಿಕೆಯಿಂದ ರಫ್ತು ಮಾಡಿ (ಆ್ಯಪ್ ಒದಗಿಸಿದರೆ).","trace.guide.3.t":"ಅಗತ್ಯಕ್ಕೆ ತಕ್ಕಂತೆ iCloud ಆನ್ ಮಾಡಿ","trace.guide.3.b":"ನಿಮ್ಮ ಸಾಧನಗಳ ನಡುವೆ ಸಿಂಕ್ ಮಾಡಬೇಕಿದ್ದರೆ ಸಿಸ್ಟಂ ಮತ್ತು ಆ್ಯಪ್‌ನಲ್ಲಿ ನೀವೇ iCloud ಆನ್ ಮಾಡಿ; ಡೆವಲಪರ್ ನಿಮ್ಮ iCloud ರುಜುವಾತು ಅಥವಾ ವಿಷಯ ಪಡೆಯುವುದಿಲ್ಲ.","app.tab.overview":"ಉತ್ಪನ್ನ ಪರಿಚಯ","app.tab.start":"ಆರಂಭಿಕ ಮಾರ್ಗದರ್ಶಿ","app.tab.privacy":"ಗೌಪ್ಯತಾ ನೀತಿ","app.tab.terms":"ಬಳಕೆದಾರ ಒಪ್ಪಂದ","app.tab.support":"ತಾಂತ್ರಿಕ ಬೆಂಬಲ","app.cta.start":"ಬಳಸಲು ಪ್ರಾರಂಭಿಸಿ","app.cta.readPrivacy":"ಗೌಪ್ಯತಾ ನೀತಿ ಓದಿ","app.shots":"ಸ್ಟೋರ್ ಸ್ಕ್ರೀನ್‌ಶಾಟ್‌ಗಳು","app.faq":"ಪದೇ ಪದೇ ಕೇಳಲಾಗುವ ಪ್ರಶ್ನೆಗಳು","app.contactTitle":"ನಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಿ","app.contactQ":"ಪ್ರಶ್ನೆಗಳಿದ್ದರೆ ದಯವಿಟ್ಟು ಸಂಪರ್ಕಿಸಿ:","app.supportContact":"ಇನ್ನೂ ಸಹಾಯ ಬೇಕೆ? ದಯವಿಟ್ಟು {email} ಗೆ ಇಮೇಲ್ ಮಾಡಿ.","app.getInStore":"{store} ನಲ್ಲಿ {app} ಪಡೆಯಿರಿ","app.legal.effective":"ಜಾರಿ ದಿನಾಂಕ","app.legal.platform":"ಬೆಂಬಲಿತ ವೇದಿಕೆಗಳು","app.legal.appname":"ಆ್ಯಪ್ ಹೆಸರು","app.footerSlogan":"ಉತ್ಪನ್ನ ಪರಿಚಯ · ಆರಂಭಿಕ ಮಾರ್ಗದರ್ಶಿ · ಗೌಪ್ಯತೆ ಮತ್ತು ಬೆಂಬಲ","tt.ui.headerSub":"GPS ಪಥ ದಾಖಲೆ · ಮಾರ್ಗ ಪುನರಾವಲೋಕನ · ಗೌಪ್ಯತೆಗೆ ಆದ್ಯತೆ","tt.ui.ovTitle":"ಸಮಯ ಮತ್ತು ಸ್ಥಳವನ್ನು ಜೋಡಿಸಿ ನಿಮ್ಮದೇ ಕಥೆ ರೂಪಿಸಿ","tt.ui.privTitle":"ದಾಖಲೆಗಳು ನಿಮ್ಮದು, ದತ್ತಾಂಶವೂ ನಿಮ್ಮದು","tt.ui.privBody":"ಖಾತೆ ಅಗತ್ಯವಿಲ್ಲ, ಜಾಹೀರಾತು ಅಥವಾ ಮೂರನೇ ಪಕ್ಷದ ಟ್ರ್ಯಾಕಿಂಗ್ ಇಲ್ಲ. ಪಥಗಳು ಡೀಫಾಲ್ಟ್ ಆಗಿ ಈ ಸಾಧನದಲ್ಲೇ ಸಂಗ್ರಹವಾಗುತ್ತವೆ; iCloud ಬ್ಯಾಕಪ್ ಸಂಪೂರ್ಣ ಐಚ್ಛಿಕ ಮತ್ತು ನಿಮ್ಮ Apple CloudKit ಖಾಸಗಿ ಡೇಟಾಬೇಸ್‌ಗೆ ಮಾತ್ರ ಹೋಗುತ್ತದೆ.","tt.ui.guideTitle":"ನಿಮ್ಮ ಮೊದಲ ಪಥದಿಂದ ಪ್ರಾರಂಭಿಸಿ","tt.ui.galleryTitle":"ಪ್ರತಿ ದಿನದ ಮಾರ್ಗದಿಂದ ಸಮಯದ ಕುರುಹುಗಳನ್ನು ನೋಡಿ","tt.ui.desc.start":"ಸ್ಥಳ ಅನುಮತಿಯಿಂದ ದೈನಂದಿನ ಪಥ ನೋಡುವವರೆಗೆ, ಬೇಗನೆ ಪ್ರಾರಂಭಿಸಿ.","tt.ui.desc.privacy":"ಈ ಆ್ಯಪ್‌ನಲ್ಲಿ ಸ್ಥಳ, ಚಲನೆ ಮತ್ತು iCloud ಬ್ಯಾಕಪ್ ಹೇಗೆ ನಿರ್ವಹಿಸಲಾಗುತ್ತದೆ ಎಂಬುದನ್ನು ತಿಳಿಯಿರಿ.","tt.ui.desc.terms":"ಈ ಆ್ಯಪ್ ಬಳಸುವ ಮೊದಲು ದಯವಿಟ್ಟು ಬಳಕೆದಾರ ಒಪ್ಪಂದವನ್ನು ಓದಿ.","tt.ui.desc.support":"ಪ್ರತಿ ಪ್ರಯಾಣವನ್ನು ಸುಲಭವಾಗಿ ದಾಖಲಿಸಲು ಮತ್ತು ಪುನರಾವಲೋಕಿಸಲು ನಾವು ನಿಮಗೆ ಸಹಾಯ ಮಾಡುತ್ತೇವೆ.","tt.ui.faq.0.q":"TimeTrails ಯಾವಾಗಲೂ ನನ್ನ ಸ್ಥಳವನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡುತ್ತದೆಯೇ?","tt.ui.faq.0.a":"ದಾಖಲೆ ನಿಮ್ಮ ನಿಯಂತ್ರಣದಲ್ಲಿದೆ ಮತ್ತು ಯಾವಾಗ ಬೇಕಾದರೂ ವಿರಾಮಗೊಳಿಸಬಹುದು. ಸಿಸ್ಟಮ್ ಸ್ಥಳವನ್ನು ಸಾಧನದಲ್ಲಿ ಪಥ ದಾಖಲಿಸಲು ಮಾತ್ರ ಬಳಸಲಾಗುತ್ತದೆ, ಮತ್ತು ದತ್ತಾಂಶ ಡೀಫಾಲ್ಟ್ ಆಗಿ ಸಾಧನದಲ್ಲೇ ಉಳಿಯುತ್ತದೆ.","tt.ui.faq.1.q":"ಸ್ಥಳ ದಾಖಲಾಗಿಲ್ಲವೇ?","tt.ui.faq.1.a":"“ಸೆಟ್ಟಿಂಗ್ಸ್ → ಗೌಪ್ಯತೆ ಮತ್ತು ಭದ್ರತೆ → ಸ್ಥಳ ಸೇವೆಗಳು”ನಲ್ಲಿ TimeTrails ಗಾಗಿ “ಯಾವಾಗಲೂ” ಆಯ್ಕೆಮಾಡಿ, ಮತ್ತು “ನಿಖರ ಸ್ಥಳ” ಹಾಗೂ ಹಿನ್ನೆಲೆ ಆ್ಯಪ್ ರಿಫ್ರೆಶ್ ಆನ್ ಮಾಡಿ.","tt.ui.faq.2.q":"iCloud ಬ್ಯಾಕಪ್ ಅನ್ನು ಹೇಗೆ ಮರುಸ್ಥಾಪಿಸುವುದು?","tt.ui.faq.2.a":"ಅದೇ Apple ID ಬಳಸಿ, iCloud ಆನ್ ಆಗಿದ್ದು ನೆಟ್‌ವರ್ಕ್ ಸರಿಯಾಗಿದ್ದಾಗ, ಸೆಟ್ಟಿಂಗ್ಸ್‌ನ “iCloud ಡೇಟಾ ಬ್ಯಾಕಪ್”ನಲ್ಲಿ ಮರುಸ್ಥಾಪಿಸಬಹುದು ಅಥವಾ ಕೈಯಾರೆ ಸಿಂಕ್ ಮಾಡಬಹುದು.","tt.ui.faq.3.q":"ದತ್ತಾಂಶವನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ಹೇಗೆ ಅಳಿಸುವುದು?","tt.ui.faq.3.a":"ಆ್ಯಪ್ ಸೆಟ್ಟಿಂಗ್ಸ್‌ನಲ್ಲಿ ಸ್ಥಳೀಯ ದತ್ತಾಂಶವನ್ನು ಅಳಿಸಬಹುದು; iCloud ಬ್ಯಾಕಪ್ ಆನ್ ಆಗಿದ್ದರೆ, ಕ್ಲೌಡ್ ಪ್ರತಿಯನ್ನೂ ಅಳಿಸಿ.","trace.ui.headerSub":"ಮಾರ್ಗ ದಾಖಲೆ · ದತ್ತಾಂಶ ನಿಯಂತ್ರಣದಲ್ಲಿ","trace.ui.ovTitle":"ಪ್ರತಿ ಪ್ರಯಾಣಕ್ಕೂ ಅನುಸರಿಸಬಹುದಾದ ಕುರುಹು ಇರಲಿ","trace.ui.privTitle":"ಸ್ಥಳೀಯ ಆದ್ಯತೆ, ದತ್ತಾಂಶ ನಿಯಂತ್ರಣದಲ್ಲಿ","trace.ui.privBody":"ಖಾತೆ ಅಗತ್ಯವಿಲ್ಲ, ಒಳಗೊಂಡ ಜಾಹೀರಾತು ಅಥವಾ ಮೂರನೇ ಪಕ್ಷದ ಅಂಕಿಅಂಶ ಇಲ್ಲ. ಪಥಗಳು ಡೀಫಾಲ್ಟ್ ಆಗಿ ಪ್ರಸ್ತುತ ಸಾಧನದಲ್ಲೇ ಉಳಿಯುತ್ತವೆ; iCloud ಸಿಂಕ್ ನೀವು ಸ್ವತಃ ಆನ್ ಮಾಡಿದಾಗ ಮಾತ್ರ ಬಳಕೆಯಾಗುತ್ತದೆ.","trace.ui.guideTitle":"ಮೊದಲ ಮಾರ್ಗದಿಂದ ಪ್ರಾರಂಭಿಸಿ","trace.ui.galleryTitle":"ಮಾರ್ಗಗಳು, ನಕ್ಷೆಗಳು ಮತ್ತು ಇತಿಹಾಸ ಪುನರಾವಲೋಕನ","trace.ui.desc.start":"ಸ್ಥಳ ಅನುಮತಿಯಿಂದ ಮಾರ್ಗ ಪುನರಾವಲೋಕನದವರೆಗೆ, ಬೇಗನೆ ಪ್ರಾರಂಭಿಸಿ.","trace.ui.desc.privacy":"ಪಥ ದತ್ತಾಂಶ, iCloud ಮತ್ತು ಸಿಸ್ಟಮ್ ಅನುಮತಿಗಳನ್ನು ಹೇಗೆ ನಿರ್ವಹಿಸಲಾಗುತ್ತದೆ ಎಂಬುದನ್ನು ತಿಳಿಯಿರಿ.","trace.ui.desc.terms":"ಈ ಆ್ಯಪ್ ಬಳಸುವ ಮೊದಲು ದಯವಿಟ್ಟು ಬಳಕೆದಾರ ಒಪ್ಪಂದವನ್ನು ಓದಿ.","trace.ui.desc.support":"ಪ್ರತಿ ಪ್ರಯಾಣವನ್ನು ಸುಲಭವಾಗಿ ದಾಖಲಿಸಲು ಮತ್ತು ನಿರ್ವಹಿಸಲು ನಾವು ನಿಮಗೆ ಸಹಾಯ ಮಾಡುತ್ತೇವೆ.","trace.ui.faq.0.q":"ಸ್ಥಳ ಅನುಮತಿಯನ್ನು ಹೇಗೆ ಹೊಂದಿಸುವುದು?","trace.ui.faq.0.a":"“ಸೆಟ್ಟಿಂಗ್ಸ್ → ಗೌಪ್ಯತೆ ಮತ್ತು ಭದ್ರತೆ → ಸ್ಥಳ ಸೇವೆಗಳು → TraceApp”ನಲ್ಲಿ “ಆ್ಯಪ್ ಬಳಸುವಾಗ” ಅಥವಾ “ಯಾವಾಗಲೂ” ಆಯ್ಕೆಮಾಡಿ, ಯಾವಾಗ ಬೇಕಾದರೂ ಆಫ್ ಮಾಡಬಹುದು.","trace.ui.faq.1.q":"ದತ್ತಾಂಶವನ್ನು ಹೇಗೆ ಅಳಿಸುವುದು?","trace.ui.faq.1.a":"ಆ್ಯಪ್‌ನಲ್ಲಿ ಒಂದು ಅಥವಾ ಎಲ್ಲಾ ದಾಖಲೆಗಳನ್ನು ಅಳಿಸಬಹುದು; ಅನ್‌ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಿದರೆ ಸ್ಥಳೀಯ ದತ್ತಾಂಶ ಅಳಿಸಲ್ಪಡುತ್ತದೆ. iCloud ಆನ್ ಆಗಿದ್ದರೆ ಸಿಂಕ್ ಆದ ಪ್ರತಿಯನ್ನು iCloudನಲ್ಲಿ ಪ್ರತ್ಯೇಕವಾಗಿ ನಿರ್ವಹಿಸಬೇಕು.","trace.ui.faq.2.q":"ಸಮಸ್ಯೆ ವರದಿ ಮಾಡುವಾಗ ಏನನ್ನು ನೀಡಬೇಕು?","trace.ui.faq.2.a":"ಪುನರುತ್ಪಾದನೆಯ ಹಂತಗಳು, ನಿರೀಕ್ಷಿತ ಮತ್ತು ವಾಸ್ತವಿಕ ಫಲಿತಾಂಶ, ಸಾಧನ ಮಾದರಿ ಮತ್ತು ಸಿಸ್ಟಮ್ ಆವೃತ್ತಿಯನ್ನು ಸೇರಿಸಲು ಸೂಚಿಸಲಾಗುತ್ತದೆ; ಸುಲಭ ಗುರುತಿಗಾಗಿ ಸ್ಕ್ರೀನ್‌ಶಾಟ್‌ಗಳನ್ನೂ ಸೇರಿಸಬಹುದು.","mem.ui.headerSub":"ವಿಶೇಷ ದಿನಗಳು · ಹುಟ್ಟುಹಬ್ಬಗಳು · ಕೌಂಟ್‌ಡೌನ್","mem.ui.ovTitle":"ದಾಖಲಿಸಲು ಯೋಗ್ಯವಾದ ಪ್ರತಿ ಬಗೆಯ ಮಹತ್ವದ ಕ್ಷಣಕ್ಕೂ","mem.ui.privTitle":"ಅನುಕೂಲತೆಗಿಂತ ಮೊದಲು ಗೌಪ್ಯತೆ","mem.ui.priv.ios":"ಖಾತೆ ಇಲ್ಲ, ಜಾಹೀರಾತು ಇಲ್ಲ, ಮೂರನೇ ಪಕ್ಷದ ಟ್ರ್ಯಾಕಿಂಗ್ ಇಲ್ಲ; ಸಿಂಕ್ ಆನ್ ಆಗಿದ್ದರೆ ಅದು ನಿಮ್ಮ iCloud ಖಾಸಗಿ ಡೇಟಾಬೇಸ್‌ಗೆ ಮಾತ್ರ ಹೋಗುತ್ತದೆ.","mem.ui.priv.hm":"ಖಾತೆ ಇಲ್ಲ, ನೆಟ್‌ವರ್ಕ್ ಇಲ್ಲ, ಕ್ಲೌಡ್ ಬ್ಯಾಕಪ್ ಇಲ್ಲ; ನಿಮ್ಮ ದಾಖಲೆಗಳು ಪ್ರಸ್ತುತ ಸಾಧನದಲ್ಲೇ ಉಳಿಯುತ್ತವೆ.","mem.ui.guideTitle":"ಮೊದಲ ದಾಖಲೆಯಿಂದ ಪ್ರಾರಂಭಿಸಿ","mem.ui.galleryTitle":"{app} ನ ವಾಸ್ತವಿಕ ಇಂಟರ್‌ಫೇಸ್ ನೋಡಿ","mem.ui.storeHint":"ಈ ಆ್ಯಪ್ ಪಡೆಯಲು {store} ನಲ್ಲಿ “{app}” ಹುಡುಕಿ.","mem.ui.desc.start":"ಮೊದಲ ರಚನೆಯಿಂದ ಅಧಿಸೂಚನೆ ಅನುಮತಿಯವರೆಗೆ, {app} ಬಳಸಲು ಬೇಗನೆ ಪ್ರಾರಂಭಿಸಿ.","mem.ui.desc.privacy":"ನೀವು ಬಳಸುತ್ತಿರುವ ವೇದಿಕೆಗೆ ಅನ್ವಯವಾಗುವ {app} ಗೌಪ್ಯತಾ ನೀತಿಯನ್ನು ಓದಿ.","mem.ui.desc.terms":"{app} ಬಳಸುವ ಮೊದಲು ದಯವಿಟ್ಟು ಈ ಬಳಕೆದಾರ ಒಪ್ಪಂದವನ್ನು ಓದಿ.","mem.ui.desc.support":"{app} ಅನ್ನು ಸುಲಭವಾಗಿ ಬಳಸಲು ನಾವು ನಿಮಗೆ ಸಹಾಯ ಮಾಡುತ್ತೇವೆ.","mem.ui.faq.0.q":"ದತ್ತಾಂಶ ಇತರ ಸಾಧನಗಳಿಗೆ ಸಿಂಕ್ ಆಗುತ್ತದೆಯೇ?","mem.ui.faq.0.a.ios":"iCloud ಗೆ ಸೈನ್ ಇನ್ ಆಗಿ ಸಿಂಕ್ ಆನ್ ಮಾಡಿದ ಬಳಿಕ, ದತ್ತಾಂಶ ನಿಮ್ಮ iCloud ಖಾಸಗಿ ಡೇಟಾಬೇಸ್ ಮೂಲಕ iPhone, iPad ಮತ್ತು Apple Watch ನಡುವೆ ಸಿಂಕ್ ಆಗುತ್ತದೆ.","mem.ui.faq.0.a.hm":"ಇಲ್ಲ. ಈ ಆವೃತ್ತಿ ನೆಟ್‌ವರ್ಕ್‌ಗೆ ಸಂಪರ್ಕಗೊಳ್ಳುವುದಿಲ್ಲ ಮತ್ತು ಕ್ಲೌಡ್ ಸಿಂಕ್ ನೀಡುವುದಿಲ್ಲ, ದತ್ತಾಂಶ ಪ್ರಸ್ತುತ ಸಾಧನದಲ್ಲೇ ಉಳಿಯುತ್ತದೆ.","mem.ui.faq.1.q":"ದತ್ತಾಂಶವನ್ನು ಹೇಗೆ ಅಳಿಸುವುದು?","mem.ui.faq.1.a.ios":"ಆ್ಯಪ್‌ನಲ್ಲಿ ದಾಖಲೆಗಳನ್ನು ಅಳಿಸಬಹುದು; ಆ್ಯಪ್ ಅನ್‌ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಿದರೆ ಸ್ಥಳೀಯ ದತ್ತಾಂಶ ಅಳಿಸಲ್ಪಡುತ್ತದೆ, iCloud ದತ್ತಾಂಶವನ್ನು ಸಿಸ್ಟಮ್‌ನ “ಸೆಟ್ಟಿಂಗ್ಸ್ → iCloud”ನಲ್ಲಿ ನಿರ್ವಹಿಸಬಹುದು.","mem.ui.faq.1.a.hm":"ಆ್ಯಪ್‌ನಲ್ಲಿ ದಾಖಲೆಗಳನ್ನು ಅಳಿಸಿ ಮರುಬಳಕೆ ಬುಟ್ಟಿಯನ್ನು ಖಾಲಿ ಮಾಡಬಹುದು; ಆ್ಯಪ್ ಅನ್‌ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಿದರೆ ಎಲ್ಲಾ ಸ್ಥಳೀಯ ದತ್ತಾಂಶ ಅಳಿಸಲ್ಪಡುತ್ತದೆ.","mem.ui.faq.2.q":"ಜ್ಞಾಪನೆ ಕಾಣಿಸದಿದ್ದರೆ ಏನು ಮಾಡಬೇಕು?","mem.ui.faq.2.a":"ದಾಖಲೆಗೆ ಜ್ಞಾಪನೆ ಹೊಂದಿಸಲಾಗಿದೆ ಮತ್ತು ಸಿಸ್ಟಮ್ ಸೆಟ್ಟಿಂಗ್ಸ್‌ನಲ್ಲಿ ಈ ಆ್ಯಪ್‌ಗೆ ಅಧಿಸೂಚನೆ ಕಳುಹಿಸಲು ಅನುಮತಿ ಇದೆ ಎಂದು ಖಚಿತಪಡಿಸಿ. ಅಧಿಸೂಚನೆ ಆಫ್ ಮಾಡಿದರೆ ಜ್ಞಾಪನೆಗಳ ಮೇಲೆ ಮಾತ್ರ ಪರಿಣಾಮ, ದಾಖಲೆಗಳ ಮೇಲಲ್ಲ.","mem.ui.pc.title":"ಮಹತ್ವದ ದಿನಗಳನ್ನು ನಿಮಗೆ ಸೂಕ್ತವಾದ ಸಾಧನದಲ್ಲಿ ಇರಿಸಿ.","mem.ui.pc.desc":"ನೀವು ಬಳಸುತ್ತಿರುವ ವೇದಿಕೆಯನ್ನು ಆಯ್ಕೆಮಾಡಿ. ಎರಡೂ ಆವೃತ್ತಿಗಳು ಸ್ಥಳೀಯ ದತ್ತಾಂಶ ಮತ್ತು ಮೂರನೇ ಪಕ್ಷದ ಟ್ರ್ಯಾಕಿಂಗ್ ಇಲ್ಲದ ತತ್ವದ ಮೇಲೆ ನಡೆಯುತ್ತವೆ, ಆದರೆ ಸಿಂಕ್ ಸಾಮರ್ಥ್ಯ, ಆ್ಯಪ್ ಹೆಸರು ಮತ್ತು ಅನ್ವಯ ಒಪ್ಪಂದ ಭಿನ್ನವಾಗಿವೆ.","mem.ui.pc.ios.desc":"ಸ್ಥಳೀಯ ಜ್ಞಾಪನೆ, ವಿಜೆಟ್, Apple Watch ಮತ್ತು ಐಚ್ಛಿಕ iCloud ಖಾಸಗಿ ಸಿಂಕ್ ಬೆಂಬಲಿಸುತ್ತದೆ.","mem.ui.pc.ios.cta":"iOS ಆವೃತ್ತಿ ನೋಡಿ","mem.ui.pc.hm.desc":"ಸಂಪೂರ್ಣ ಸ್ಥಳೀಯ ಆವೃತ್ತಿ: ನೆಟ್‌ವರ್ಕ್ ಇಲ್ಲ, ಕ್ಲೌಡ್ ಸಿಂಕ್ ಇಲ್ಲ, ದತ್ತಾಂಶ ಸಾಧನದ ಆ್ಯಪ್ ಸ್ಯಾಂಡ್‌ಬಾಕ್ಸ್‌ನಲ್ಲೇ ಉಳಿಯುತ್ತದೆ.","mem.ui.pc.hm.cta":"HarmonyOS ಆವೃತ್ತಿ ನೋಡಿ"};export{e as default};
